from pathlib import Path
import json,sys
P=Path(__file__).resolve().parent
B=P.parents[3]
sys.path.insert(0,str(B))
from substantive_impact import validate
from reference_coherence import accept_checks
sources=json.loads((P/'source.json').read_text())
snapshot=json.loads((P/'reference-targets.json').read_text())
checks={
'L1234-1': 'Le préavis patronal du contrat nouveau est de quinze jours calendaires, même en cas de faute grave ; les règles antérieures subsistent pour les anciens contrats. La dispense légale de départ vers un autre emploi conservée ici est spéciale et favorable ; les autorisations de rupture restent distinctes.',
'L1241-1': 'Aucun nouveau CDD ni renouvellement n’est permis après la réforme ; les anciens contrats gardent terme et créances. Une conversion ne réinitialise ni ancienneté ni essai. La durée de l’accompagnement ne termine pas l’emploi ; les aides autonomes restent ouvertes.',
'L1221-2': 'Le contrat unique nouveau est sans terme, même si le parcours ou la formation est borné. Les textes d’insertion reprennent cette séparation ; ni cumul ni dispense de durée minimale n’autorise une embauche future à terme.',
'L1243-2': 'Le projet abroge la règle pour les contrats futurs mais conserve pour les anciens CDD le départ vers un CDI, son plafond favorable de deux semaines et la dispense consentie. Le départ spécial sans préavis après une mise en situation demeure.',
'L1234-9': 'Indemnité ordinaire patronale seulement : zéro avant un an, puis 0,20 mois par année totale, première année comprise, prorata des mois complets, plafond légal six mois, exception de faute grave. Droits antérieurs, dommages et indemnités spéciales distincts ; aucune indemnité patronale créée par la démission.',
'L1242-3': 'L’autorisation de CDD d’insertion est abrogée prospectivement sans retirer aides, exonérations et formation autonomes. Le parcours et ses prolongations ne recréent pas un CDD. Les contrats antérieurs conservent leurs engagements et le soutien reste soumis aux conditions propres.'}
rows=[]
for a in sources:
    body=a['previous_draft']['proposed_xml']
    old='en cas de cumul avec un autre contrat à temps partiel afin d’atteindre un temps plein ou une durée globale au moins égale à celle de l’article L. 3123-27.'
    assert body.count(old)==1
    body=body.replace(old,'en cas de cumul avec un autre contrat de travail à temps partiel. La dispense liée au cumul n’est subordonnée à aucune durée globale minimale d’activité et ne requiert aucune autorisation ni attestation particulière. La durée convenue reste garantie par le contrat ; elle ne peut être réduite unilatéralement par l’employeur.')
    body=body.replace('Les contrats conclus avant la réforme conservent leurs termes, créances et droits selon l’article L. 1241-1.','La suppression de la condition de durée globale minimale de cumul s’applique aux situations éligibles en cours et futures à compter de l’entrée en vigueur de la réforme ; elle ne réduit ni la durée contractuelle garantie ni la rémunération correspondante. Sous cette réserve favorable, les contrats conclus avant la réforme conservent leurs termes, créances et droits selon l’article L. 1241-1.')
    row={k:a[k]for k in ('code_id','source_id','source_sha256','number')}
    row.update(status='rewrite_draft',proposed_xml=body,
      reason='Supprime le seuil global du cumul encore rattaché au minimum de vingt-quatre heures de L. 3123-27, devenu inopérant. La dispense du minimum spécial de vingt heures vaut sans seuil global, dans les situations éligibles anciennes et futures, sans autorisation ni attestation nouvelle. Le contrat unique déjà proposé ne compte pas comme une seconde réduction.',
      review_notes='Source et note entières, proposition antérieure, L. 3123-7/19/27 et les six cibles du contrat unique lus. L. 3123-27 proposé ne fixe plus de minimum numérique ; la dispense est désormais autonome. Le minimum spécial de vingt heures hors cumul et la dérogation propre aux chantiers restent intacts. Le calendrier d’accompagnement ajouté par le précédent projet est conservé et déclaré comme complexité nouvelle face à la source ; aucun solde net global n’est affirmé. L’aide ne fixe pas le terme de l’emploi. Départ sans préavis vers un nouvel emploi, droits des anciens contrats, ancienneté et recours conservés. La note historique de décembre2020 ne fixe pas la date de la réforme proposée.',
      benefit_review='Maintenus : dérogation pour les personnes condamnées sous aménagement de peine, prolongation pour achever la formation, faveur aux plus de cinquante ans et travailleurs handicapés, et selon l’article prolongations pour difficultés particulièrement importantes dans la limite de soixante mois. Le cumul ouvre désormais une dispense sans seuil global ; la dispense contractuelle propre aux chantiers reste intacte. Suspensions, départ sans préavis vers un nouvel emploi, formation qualifiante et validation des trimestres restent à leurs conditions propres. Les aides et exonérations autonomes demeurent ouvertes aux futures situations éligibles, sans inventer de subvention nouvelle.')
    row['reference_checks']=[dict(target_key=k,view_sha256=snapshot['targets'][k]['view_sha256'],assessment=checks[snapshot['targets'][k]['number']])for k in snapshot['requirements'][a['code_id']+'|'+a['source_id']]]
    common=dict(affected_population='Salariés des structures d’insertion visées, anciens contrats et nouveaux contrats uniques dans leurs champs respectifs.',conditions_and_transition='À l’entrée en vigueur de la réforme ; durée et rémunération garanties et créances conservées, minimum spécial hors dispense et autres dérogations favorables maintenus.',replacement_or_new_burdens='Aucune formalité particulière de cumul ; contrat écrit et accompagnement demeurent. Le calendrier distinct du parcours créé par le précédent projet est déclaré séparément.')
    effects=[dict(common,kind='relief_extended',measure_id='emploi-insertion-cumul-sans-plancher-global',description='Dispense du minimum spécial de vingt heures en cas de cumul sans seuil global.',before='Cumul atteignant un temps plein ou le plancher de L. 3123-27, vingt-quatre heures à défaut d’accord.',after='Cumul avec un autre contrat à temps partiel, sans seuil global ni autorisation ou attestation particulière.',unit='legal_duty',source_quote="en cas de cumul avec un autre contrat de travail à temps partiel, afin d'atteindre une durée globale d'activité correspondant à un temps plein ou au moins égale à la durée mentionnée à l'article L. 3123-27.",proposed_quote='La dispense liée au cumul n’est subordonnée à aucune durée globale minimale d’activité et ne requiert aucune autorisation ni attestation particulière.'),
      dict(common,kind='complexity_added',measure_id='insertion-parcours-distinct-emploi',description='Calendrier d’accompagnement distinct de la durée de l’emploi.',before='Minimum contractuel de quatre mois et maximum de vingt-quatre mois attachés au CDD.',after='Parcours initial d’au moins quatre mois, périodes limitées à vingt-quatre mois, distinct du contrat sans terme ; prolongations conservées.',unit='regime',source_quote="La durée de ces contrats ne peut être inférieure à quatre mois, sauf pour les personnes ayant fait l'objet d'une condamnation et bénéficiant d'un aménagement de peine.",proposed_quote='Le parcours spécifique d’accompagnement est organisé pour une période initiale d’au moins quatre mois, sauf pour les personnes condamnées bénéficiant d’un aménagement de peine.')]
    row['substantive_impact']=dict(version=1,classification='mixed',assessment='Retrait concret du seuil global de cumul lié au minimum général de vingt-quatre heures. La séparation du calendrier d’accompagnement et de l’emploi est une complexité nouvelle du projet face à la source. Le contrat unique est une mesure commune déjà portée par ses articles de principe, sans seconde réduction revendiquée.',scope_limitations='Le minimum spécial de vingt heures hors dispense et les conditions propres des aides et de la retraite subsistent. Aucun coût national ni solde net de complexité des cinq codes n’est établi.',new_burdens_review='Aucune nouvelle formalité pour le cumul ; durée contractuelle et rémunération garanties. La gestion distincte du parcours de quatre à vingt-quatre mois est conservée du précédent projet et déclarée comme complexité ajoutée, même si elle évite le terme automatique de l’emploi.',effects=effects)
    validate(row,a,required=True)
    rows.append(row)
accept_checks(rows,sources,snapshot)
(P/'answer.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
print('Trois candidatures intégrales ancrées et vérifiées ; aucune intégration.')
